import{_ as r,C as a,o as s,c as l,E as e,a7 as d}from"./chunks/framework.FWlv_suP.js";const b=JSON.parse('{"title":"Qurio Data Collection","description":"A summary of Qurio data practices.","frontmatter":{"title":"Qurio Data Collection","description":"A summary of Qurio data practices."},"headers":[],"relativePath":"apps/qurio/data-collection.md","filePath":"apps/qurio/data-collection.md"}'),c={name:"apps/qurio/data-collection.md"};function p(u,o,m,h,f,v){const t=a("AppBreadcrumbs"),i=a("AppSubnav"),n=a("CopyStandaloneUrl");return s(),l("div",null,[e(t,{"app-id":"qurio",current:"Data Collection"}),e(i,{"app-id":"qurio"}),e(n,{path:"/data-collection/qurio",label:"Copy standalone data-collection URL","copied-label":"Data Collection URL copied","document-name":"Qurio data-collection page"}),o[0]||(o[0]=d('<h1 id="qurio-data-collection" tabindex="-1">Qurio Data Collection <a class="header-anchor" href="#qurio-data-collection" aria-label="Permalink to &quot;Qurio Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> September 8, 2026</p><h2 id="information-processed" tabindex="-1">Information processed <a class="header-anchor" href="#information-processed" aria-label="Permalink to &quot;Information processed&quot;">​</a></h2><p>Qurio processes a display name, email address, Supabase authentication credentials, email-verification status, account status, and role. Passwords are not available to the developer in plaintext. Account administration may record approval, denial, suspension, reactivation, role changes, reasons, and audit details.</p><p>Qurio stores language, theme, curriculum, grade, selected exam plan, study progress, content identifiers, quiz attempts and answers, hint use, timing, scores, pass results, exam-plan tasks, and timestamps.</p><h2 id="local-information" tabindex="-1">Local information <a class="header-anchor" href="#local-information" aria-label="Permalink to &quot;Local information&quot;">​</a></h2><p>Preferences and progress are cached locally. Optional PIN protection stores a salted password-derived verifier in IndexedDB. Android biometric unlock uses an encrypted secret protected by Android Keystore; Qurio does not collect biometric templates.</p><p>Enabled reminder days, time, and permission-prompt state stay locally on the device. No push-notification token is uploaded.</p><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p>Supabase processes authentication, profile, authorization, learning, settings, and audit data. GitHub hosts the web client and learning content. The authentication email provider processes addresses and delivery metadata for verification and password-reset messages. Providers also receive normal connection and security metadata.</p><h2 id="advertising-and-analytics" tabindex="-1">Advertising and analytics <a class="header-anchor" href="#advertising-and-analytics" aria-label="Permalink to &quot;Advertising and analytics&quot;">​</a></h2><p>Qurio has no advertising, developer-operated analytics, or tracking SDK.</p><p>Questions: <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',13))])}const g=r(c,[["render",p]]);export{b as __pageData,g as default};
